31	export class Ky {
32		static create(input: Input, options: Options): ResponsePromise {
33			const ky = new Ky(input, options);
34	
35			const function_ = async (): Promise<Response> => {
36				if (typeof ky.#options.timeout === 'number' && ky.#options.timeout > maxSafeTimeout) {
37					throw new RangeError(`The \`timeout\` option cannot be greater than ${maxSafeTimeout}`);
38				}
39	
40				// Delay the fetch so that body method shortcuts can set the Accept header
41				await Promise.resolve();
42				// Before using ky.request, _fetch clones it and saves the clone for future retries to use.
43				// If retry is not needed, close the cloned request's ReadableStream for memory safety.
44				let response = await ky.#fetch();
45	
46				for (const hook of ky.#options.hooks.afterResponse) {
47					// eslint-disable-next-line no-await-in-loop
48					const modifiedResponse = await hook(
49						ky.request,
50						ky.#getNormalizedOptions(),
51						ky.#decorateResponse(response.clone()),
52						{retryCount: ky.#retryCount},
53					);
54	
55					if (modifiedResponse instanceof globalThis.Response) {
56						response = modifiedResponse;
57					}
58				}
59	
60				ky.#decorateResponse(response);
61	
62				if (!response.ok && (
63					typeof ky.#options.throwHttpErrors === 'function'
64						? ky.#options.throwHttpErrors(response.status)
65						: ky.#options.throwHttpErrors
66				)) {
67					let error = new HTTPError(response, ky.request, ky.#getNormalizedOptions());
68	
69					for (const hook of ky.#options.hooks.beforeError) {
70						// eslint-disable-next-line no-await-in-loop
71						error = await hook(error, {retryCount: ky.#retryCount});
72					}
73	
74					throw error;
75				}
76	
77				// If `onDownloadProgress` is passed, it uses the stream API internally
78				if (ky.#options.onDownloadProgress) {
79					if (typeof ky.#options.onDownloadProgress !== 'function') {
80						throw new TypeError('The `onDownloadProgress` option must be a function');
81					}
82	
83					if (!supportsResponseStreams) {
84						throw new Error('Streams are not supported in your environment. `ReadableStream` is missing.');
85					}
86	
87					return streamResponse(response.clone(), ky.#options.onDownloadProgress);
88				}
89	
90				return response;
91			};
92	
93			const isRetriableMethod = ky.#options.retry.methods.includes(ky.request.method.toLowerCase());
94			const result = (isRetriableMethod ? ky.#retry(function_) : function_())
95				.finally(async () => {
96					const originalRequest = ky.#originalRequest;
97					const cleanupPromises = [];
98	
99					if (originalRequest && !originalRequest.bodyUsed) {
100						cleanupPromises.push(originalRequest.body?.cancel());
101					}
102	
103					if (!ky.request.bodyUsed) {
104						cleanupPromises.push(ky.request.body?.cancel());
105					}
106	
107					await Promise.all(cleanupPromises);
108				}) as ResponsePromise;
109	
110			for (const [type, mimeType] of Object.entries(responseTypes) as ObjectEntries<typeof responseTypes>) {
111				// Only expose `.bytes()` when the environment implements it.
112				if (
113					type === 'bytes'
114					&& typeof (globalThis.Response?.prototype as unknown as {bytes?: unknown})?.bytes !== 'function'
115				) {
116					continue;
117				}
118	
119				result[type] = async () => {
120					// eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
121					ky.request.headers.set('accept', ky.request.headers.get('accept') || mimeType);
122	
123					const response = await result;
124	
125					if (type === 'json') {
126						if (response.status === 204) {
127							return '';
128						}
129	
130						const text = await response.text();
131						if (text === '') {
132							return '';
133						}
134	
135						if (options.parseJson) {
136							return options.parseJson(text);
137						}
138	
139						return JSON.parse(text);
140					}
141	
142					return response[type]();
143				};
144			}
145	
146			return result;
147		}
148	
149		// eslint-disable-next-line unicorn/prevent-abbreviations
150		static #normalizeSearchParams(searchParams: SearchParamsOption): SearchParamsOption {
151			// Filter out undefined values from plain objects
152			if (searchParams && typeof searchParams === 'object' && !Array.isArray(searchParams) && !(searchParams instanceof URLSearchParams)) {
153				return Object.fromEntries(
154					Object.entries(searchParams).filter(([, value]) => value !== undefined),
155				);
156			}
157	
158			return searchParams;
159		}
160	
161		public request: Request;
162		#abortController?: AbortController;
163		#retryCount = 0;
164		// eslint-disable-next-line @typescript-eslint/prefer-readonly -- False positive: #input is reassigned on line 202
165		#input: Input;
166		readonly #options: InternalOptions;
167		#originalRequest?: Request;
168		readonly #userProvidedAbortSignal?: AbortSignal;
169		#cachedNormalizedOptions?: NormalizedOptions;
170	
171		// eslint-disable-next-line complexity
172		constructor(input: Input, options: Options = {}) {
173			this.#input = input;
174	
175			this.#options = {
176				...options,
177				headers: mergeHeaders((this.#input as Request).headers, options.headers),
178				hooks: mergeHooks(
179					{
180						beforeRequest: [],
181						beforeRetry: [],
182						beforeError: [],
183						afterResponse: [],
184					},
185					options.hooks,
186				),
187				method: normalizeRequestMethod(options.method ?? (this.#input as Request).method ?? 'GET'),
188				// eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
189				prefixUrl: String(options.prefixUrl || ''),
190				retry: normalizeRetryOptions(options.retry),
191				throwHttpErrors: options.throwHttpErrors ?? true,
192				timeout: options.timeout ?? 10_000,
193				fetch: options.fetch ?? globalThis.fetch.bind(globalThis),
194				context: options.context ?? {},
195			};
196	
197			if (typeof this.#input !== 'string' && !(this.#input instanceof URL || this.#input instanceof globalThis.Request)) {
198				throw new TypeError('`input` must be a string, URL, or Request');
199			}
200	
201			if (this.#options.prefixUrl && typeof this.#input === 'string') {
202				if (this.#input.startsWith('/')) {
203					throw new Error('`input` must not begin with a slash when using `prefixUrl`');
204				}
205	
206				if (!this.#options.prefixUrl.endsWith('/')) {
207					this.#options.prefixUrl += '/';
208				}
209	
210				this.#input = this.#options.prefixUrl + this.#input;
211			}
212	
213			if (supportsAbortController && supportsAbortSignal) {
214				this.#userProvidedAbortSignal = this.#options.signal ?? (this.#input as Request).signal;
215				this.#abortController = new globalThis.AbortController();
216				this.#options.signal = this.#userProvidedAbortSignal ? AbortSignal.any([this.#userProvidedAbortSignal, this.#abortController.signal]) : this.#abortController.signal;
217			}
218	
219			if (supportsRequestStreams) {
220				// @ts-expect-error - Types are outdated.
221				this.#options.duplex = 'half';
222			}
223	
224			if (this.#options.json !== undefined) {
225				this.#options.body = this.#options.stringifyJson?.(this.#options.json) ?? JSON.stringify(this.#options.json);
226				this.#options.headers.set('content-type', this.#options.headers.get('content-type') ?? 'application/json');
227			}
228	
229			// To provide correct form boundary, Content-Type header should be deleted when creating Request from another Request with FormData/URLSearchParams body
230			// Only delete if user didn't explicitly provide a custom content-type
231			const userProvidedContentType = options.headers && new globalThis.Headers(options.headers as HeadersInit).has('content-type');
232			if (
233				this.#input instanceof globalThis.Request
234				&& ((supportsFormData && this.#options.body instanceof globalThis.FormData) || this.#options.body instanceof URLSearchParams)
235				&& !userProvidedContentType
236			) {
237				this.#options.headers.delete('content-type');
238			}
239	
240			this.request = new globalThis.Request(this.#input, this.#options);
241	
242			if (hasSearchParameters(this.#options.searchParams)) {
243				// eslint-disable-next-line unicorn/prevent-abbreviations
244				const textSearchParams = typeof this.#options.searchParams === 'string'
245					? this.#options.searchParams.replace(/^\?/, '')
246					: new URLSearchParams(Ky.#normalizeSearchParams(this.#options.searchParams) as unknown as SearchParamsInit).toString();
247				// eslint-disable-next-line unicorn/prevent-abbreviations
248				const searchParams = '?' + textSearchParams;
249				const url = this.request.url.replace(/(?:\?.*?)?(?=#|$)/, searchParams);
250	
251				// Recreate request with the updated URL. We already have all options in this.#options, including duplex.
252				this.request = new globalThis.Request(url, this.#options as RequestInit);
253			}
254	
255			// If `onUploadProgress` is passed, it uses the stream API internally
256			if (this.#options.onUploadProgress) {
257				if (typeof this.#options.onUploadProgress !== 'function') {
258					throw new TypeError('The `onUploadProgress` option must be a function');
259				}
260	
261				if (!supportsRequestStreams) {
262					throw new Error('Request streams are not supported in your environment. The `duplex` option for `Request` is not available.');
263				}
264	
265				const originalBody = this.request.body;
266				if (originalBody) {
267					// Pass original body to calculate size correctly (before it becomes a stream)
268					this.request = streamRequest(this.request, this.#options.onUploadProgress, this.#options.body);
269				}
270			}
271		}
272	
273		#calculateDelay(): number {
274			const retryDelay = this.#options.retry.delay(this.#retryCount);
275	
276			let jitteredDelay = retryDelay;
277			if (this.#options.retry.jitter === true) {
278				jitteredDelay = Math.random() * retryDelay;
279			} else if (typeof this.#options.retry.jitter === 'function') {
280				jitteredDelay = this.#options.retry.jitter(retryDelay);
281	
282				if (!Number.isFinite(jitteredDelay) || jitteredDelay < 0) {
283					jitteredDelay = retryDelay;
284				}
285			}
286	
287			return Math.min(this.#options.retry.backoffLimit, jitteredDelay);
288		}
289	
290		async #calculateRetryDelay(error: unknown) {
291			this.#retryCount++;
292	
293			if (this.#retryCount > this.#options.retry.limit) {
294				throw error;
295			}
296	
297			// Wrap non-Error throws to ensure consistent error handling
298			const errorObject = error instanceof Error ? error : new NonError(error);
299	
300			// User-provided shouldRetry function takes precedence over all other checks
301			if (this.#options.retry.shouldRetry !== undefined) {
302				const result = await this.#options.retry.shouldRetry({error: errorObject, retryCount: this.#retryCount});
303	
304				// Strict boolean checking - only exact true/false are handled specially
305				if (result === false) {
306					throw error;
307				}
308	
309				if (result === true) {
310					// Force retry - skip all other validation and return delay
311					return this.#calculateDelay();
312				}
313	
314				// If undefined or any other value, fall through to default behavior
315			}
316	
317			// Default timeout behavior
318			if (isTimeoutError(error) && !this.#options.retry.retryOnTimeout) {
319				throw error;
320			}
321	
322			if (isHTTPError(error)) {
323				if (!this.#options.retry.statusCodes.includes(error.response.status)) {
324					throw error;
325				}
326	
327				const retryAfter = error.response.headers.get('Retry-After')
328					?? error.response.headers.get('RateLimit-Reset')
329					?? error.response.headers.get('X-RateLimit-Retry-After') // Symfony-based services
330					?? error.response.headers.get('X-RateLimit-Reset') // GitHub
331					?? error.response.headers.get('X-Rate-Limit-Reset'); // Twitter
332				if (retryAfter && this.#options.retry.afterStatusCodes.includes(error.response.status)) {
333					let after = Number(retryAfter) * 1000;
334					if (Number.isNaN(after)) {
335						after = Date.parse(retryAfter) - Date.now();
336					} else if (after >= Date.parse('2024-01-01')) {
337						// A large number is treated as a timestamp (fixed threshold protects against clock skew)
338						after -= Date.now();
339					}
340	
341					const max = this.#options.retry.maxRetryAfter ?? after;
342					// Don't apply jitter when server provides explicit retry timing
343					return after < max ? after : max;
344				}
345	
346				if (error.response.status === 413) {
347					throw error;
348				}
349			}
350	
351			return this.#calculateDelay();
352		}
353	
354		#decorateResponse(response: Response): Response {
355			if (this.#options.parseJson) {
356				response.json = async () => this.#options.parseJson!(await response.text());
357			}
358	
359			return response;
360		}
361	
362		async #retry<T extends (...arguments_: any) => Promise<any>>(function_: T): Promise<ReturnType<T> | Response | void> {
363			try {
364				return await function_();
365			} catch (error) {
366				const ms = Math.min(await this.#calculateRetryDelay(error), maxSafeTimeout);
367				if (this.#retryCount < 1) {
368					throw error;
369				}
370	
371				// Only use user-provided signal for delay, not our internal abortController
372				await delay(ms, this.#userProvidedAbortSignal ? {signal: this.#userProvidedAbortSignal} : {});
373	
374				for (const hook of this.#options.hooks.beforeRetry) {
375					// eslint-disable-next-line no-await-in-loop
376					const hookResult = await hook({
377						request: this.request,
378						options: this.#getNormalizedOptions(),
379						error: error as Error,
380						retryCount: this.#retryCount,
381					});
382	
383					// If a Request is returned, use it for the retry
384					if (hookResult instanceof globalThis.Request) {
385						this.request = hookResult;
386						break;
387					}
388	
389					// If a Response is returned, use it and skip the retry
390					if (hookResult instanceof globalThis.Response) {
391						return hookResult;
392					}
393	
394					// If `stop` is returned from the hook, the retry process is stopped
395					if (hookResult === stop) {
396						return;
397					}
398				}
399	
400				return this.#retry(function_);
401			}
402		}
403	
404		async #fetch(): Promise<Response> {
405			// Reset abortController if it was aborted (happens on timeout retry)
406			if (this.#abortController?.signal.aborted) {
407				this.#abortController = new globalThis.AbortController();
408				this.#options.signal = this.#userProvidedAbortSignal ? AbortSignal.any([this.#userProvidedAbortSignal, this.#abortController.signal]) : this.#abortController.signal;
409				// Recreate request with new signal
410				this.request = new globalThis.Request(this.request, {signal: this.#options.signal});
411			}
412	
413			for (const hook of this.#options.hooks.beforeRequest) {
414				// eslint-disable-next-line no-await-in-loop
415				const result = await hook(
416					this.request,
417					this.#getNormalizedOptions(),
418					{retryCount: this.#retryCount},
419				);
420	
421				if (result instanceof Request) {
422					this.request = result;
423					break;
424				}
425	
426				if (result instanceof Response) {
427					return result;
428				}
429			}
430	
431			const nonRequestOptions = findUnknownOptions(this.request, this.#options);
432	
433			// Cloning is done here to prepare in advance for retries
434			this.#originalRequest = this.request;
435			this.request = this.#originalRequest.clone();
436	
437			if (this.#options.timeout === false) {
438				return this.#options.fetch(this.#originalRequest, nonRequestOptions);
439			}
440	
441			return timeout(this.#originalRequest, nonRequestOptions, this.#abortController, this.#options as TimeoutOptions);
442		}
443	
444		#getNormalizedOptions(): NormalizedOptions {
445			if (!this.#cachedNormalizedOptions) {
446				const {hooks, ...normalizedOptions} = this.#options;
447				this.#cachedNormalizedOptions = Object.freeze(normalizedOptions) as NormalizedOptions;
448			}
449	
450			return this.#cachedNormalizedOptions;
451		}
452	}
